__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Shared memory for A and B
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    // C sub-element for this thread
    float Cvalue = 0;

    // Loop over the K dimension (N in this case)
    for (int k = 0; k < (N + TILE_DIM - 1) / TILE_DIM; ++k) {
        // Load block of A into shared memory
        int A_row_global = by * TILE_DIM + ty;
        int A_col_global = k * TILE_DIM + tx;
        if (A_row_global < N && A_col_global < N) {
            As[ty][tx] = A[A_row_global * N + A_col_global];
        } else {
            As[ty][tx] = 0.0f; // Handle out-of-bounds with 0
        }

        // Load block of B into shared memory
        int B_row_global = k * TILE_DIM + ty;
        int B_col_global = bx * TILE_DIM + tx;
        if (B_row_global < N && B_col_global < N) {
            Bs[ty][tx] = B[B_row_global * N + B_col_global];
        } else {
            Bs[ty][tx] = 0.0f; // Handle out-of-bounds with 0
        }

        __syncthreads();

        // Perform computation for the current tile
        for (int i = 0; i < TILE_DIM; ++i) {
            Cvalue += As[ty][i] * Bs[i][tx];
        }
        __syncthreads();
    }

    // Write the result to global memory
    int C_row_global = by * TILE_DIM + ty;
    int C_col_global = bx * TILE_DIM + tx;
    if (C_row_global < N && C_col_global < N) {
        C[C_row_global * N + C_col_global] = Cvalue;
