    float Cvalue[BLOCK_SIZE_Y][BLOCK_SIZE_X];
    for (int y = 0; y < BLOCK_SIZE_Y; ++y) {
        for (int x = 0; x < BLOCK_SIZE_X; ++x) {
            Cvalue[y][x] = 0.0f;
        }
    }

    // Loop over the K dimension (N in this case)
    for (int k = 0; k < (N + TILE_DIM - 1) / TILE_DIM; ++k) {
        // Load block of A into shared memory
        for (int y_offset = 0; y_offset < BLOCK_SIZE_Y; ++y_offset) {
            for (int x_offset = 0; x_offset < BLOCK_SIZE_X; ++x_offset) {
                int A_row_global = by * TILE_DIM + ty * BLOCK_SIZE_Y + y_offset;
                int A_col_global = k * TILE_DIM + tx * BLOCK_SIZE_X + x_offset;
